{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening components in storage, retrieve them, perform fastening on the workpiece, and return the tool to the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "robot_arm",
        "entity_kind": "OBJECT",
        "function": "Manipulates objects, opens storage, and performs the fastening action.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "robotic arm",
          "manipulator"
        ],
        "required_properties": [
          "gripper",
          "mobility"
        ]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The assembly that requires fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "assembly",
          "fixture",
          "part"
        ],
        "required_properties": [
          "surface",
          "mounting_point"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Implements the driving of the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "tool"
        ],
        "required_properties": [
          "handle",
          "driving_tip"
        ]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The material used to secure the workpiece.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "screw",
          "bolt",
          "pin"
        ],
        "required_properties": [
          "thread",
          "head"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the workpiece sits and where the tool is placed.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "table",
          "bench",
          "surface"
        ],
        "required_properties": [
          "flat",
          "stable"
        ]
      },
      {
        "id": "storage_container",
        "entity_kind": "REGION",
        "function": "Enclosed space where components are kept.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "cabinet",
          "drawer",
          "box"
        ],
        "required_properties": [
          "enclosed",
          "openable"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_fit",
        "relation": "fits",
        "participant_roles": [
          "fastener",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "tool_capability",
        "relation": "drives",
        "participant_roles": [
          "fastening_tool",
          "fastener"
        ]
      ,
        "required": true
      },
      {
        "id": "storage_dependency",
        "relation": "contains",
        "participant_roles": [
          "storage_container",
          "fastener"
        ]
      ,
        "required": true
      },
      {
        "id": "tool_location_dependency",
        "relation": "located_in_or_on",
        "participant_roles": [
          "storage_container",
          "fastening_tool"
        ],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_retrieve",
        "operation": "search_and_open",
        "participant_roles": [
          "robot_arm",
          "storage_container"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "identify_components",
        "operation": "inspect",
        "participant_roles": [
          "robot_arm",
          "storage_container",
          "fastener",
          "fastening_tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "pick_fastener",
        "operation": "pick",
        "participant_roles": [
          "robot_arm",
          "fastener",
          "storage_container"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "pick_tool",
        "operation": "pick",
        "participant_roles": [
          "robot_arm",
          "fastening_tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "fasten",
        "participant_roles": [
          "robot_arm",
          "fastener",
          "fastening_tool",
          "workpiece"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "cleanup",
        "operation": "place",
        "participant_roles": [
          "robot_arm",
          "fastening_tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "robot_arm": [
        {
          "label": "white_articulated_arm",
          "visual_description": "Large white robotic arm structure visible in foreground of all images."
        }
      ],
      "workpiece": [
        {
          "label": "grey_base_yellow_part",
          "visual_description": "Small assembly on the wooden table consisting of a grey base and a yellow component."
        }
      ],
      "fastening_tool": [
        {
          "label": "yellow_handle_object",
          "visual_description": "Object with a yellow handle sitting on the black tray on the table (Image 1)."
        }
      ],
      "storage_container": [
        {
          "label": "blue_cabinet",
          "visual_description": "Tall blue cabinet with a door standing against the wall behind the table."
        },
        {
          "label": "desk_drawers",
          "visual_description": "Two blue drawers underneath the wooden table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Closed blue cabinet with a silver handle.",
        "reason": "Likely contains tools or hardware supplies given its proximity to the workbench."
      },
      {
        "id": "desk_drawers",
        "label": "desk_drawers",
        "visual_description": "Closed blue drawers with silver handles.",
        "reason": "Common location for small items like screws or pins."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "desk_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
